"""Knowledge base, part 13: nutrition deep dive: calories and macros of specific foods (incl. Uzbek market foods; values are rounded
approximations on purpose), meal prep, budget, halal, kids and teens, eating out, alcohol, fasting variants, supplements A-Z with evidence
levels (no doses). Row format as in assistant_kb_site.py."""

NOTE_UZ = " Qiymatlar taxminiy (pishirish va yog' miqdoriga qarab o'zgaradi)."
NOTE_RU = " Значения примерные (зависят от способа приготовления и жира)."
NOTE_EN = " Values are approximate (they vary with cooking and fat)."


def F(eid, kuz, kru, ken, uz, ru, en, links=()):
    return ("fd_" + eid, "food", kuz, kru, ken, uz, ru, en, links)


def FN(eid, kuz, kru, ken, uz, ru, en, links=()):
    """A food entry that carries the 'approximate values' note."""
    return F(eid, kuz, kru, ken, uz + NOTE_UZ, ru + NOTE_RU, en + NOTE_EN, links)


